    void xValidationIsNonFixedValueBlank(DataTable dt)
    {
        try
        {
            decimal Total = 0;
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                if (bplib.clsWebLib.GetBoolData(dt.Rows[i]["IsSelectSlrHd"].ToString().Trim()))
                {
                    bool IsNA = bplib.clsWebLib.GetBoolData(dt.Rows[i]["IsSelectSlrHd"].ToString().Trim());
                    if (Convert.ToDecimal(dt.Rows[i]["FixedValue"].ToString().Trim()) == 0 && IsNA == false)
                    {
                        if (Convert.ToDecimal(dt.Rows[i]["EntryAmount"].ToString().Trim()) <= 0)
                        {
                            throw new Exception("No amount is given for 'Salary Head' [" + dt.Rows[i]["SalaryHead"].ToString() + "]...");//
                        }
                    }
                    Total += Convert.ToDecimal(dt.Rows[i]["EntryAmount"].ToString().Trim());
                }
            }

            if (Total <= 0)
            {
                throw new Exception("No amount is given...");
            }
        }
        catch (Exception ex)
        {
            throw ex;
        }
    }

