    public DateTime GetEffectiveDate(CustomParaNew para)
    {
        clsSalaryInfo obs = null;
        DataSet dsLocal = null;
        string sCutoffDate = null;
        try
        {
            //(string)Session["LOGIN_GROUP_ID"].ToString().Trim()
            //(string)Session["COMPANY_ID"].ToString().Trim()
            //ddlPlant.SelectedValue.ToString().Trim()
            //lblEmpSystemId.Text.ToString().Trim()

            obs = new clsSalaryInfo();
            obs.GetCutOffDate(para.CompanyGroupId, para.CompanyId, para.PlantId, para.EmployeeId, out dsLocal);
            //ValidateDate(dsLocal, "CutoffDate");


            if (!string.IsNullOrEmpty(para.CuttOffDate))
            {
                sCutoffDate = para.CuttOffDate;
            }
            else
            {
                if (dsLocal.Tables[0].Rows.Count > 0)
                {
                    sCutoffDate = dsLocal.Tables[0].Rows[0]["CutOffDate"].ToString();
                }
            }


            //obs.GetEmployeeDOJ(para.EmployeeId, out dsLocal);
            //ValidateDate(dsLocal, "DOJ");
            //DateTime dDOJ = Convert.ToDateTime(dsLocal.Tables[0].Rows[0]["DOJ"].ToString());
            DateTime dDOJ = Convert.ToDateTime(para.DOJ);
            DateTime dCutoffDate = Convert.ToDateTime(sCutoffDate);
            if (dCutoffDate > dDOJ)
            {
                return dCutoffDate;
            }
            else
            {
                return dDOJ;
            }
        }
        catch (Exception ex)
        {
            throw ex;
        }
    }
