            _para.EmployeeCode = dr["EmployeeCode"].ToString();
            _para.EmployeeName = dr["EmployeeName"].ToString();
            // _para.EmpTaxGroupPk= dr["TaxGroupIDSR"].ToString();
            _para.DOJ = dr["DOJ"].ToString();
            _para.DesignationGroupId = dr["DesignationGroupId"].ToString();
            _para.BudgetCodeId = dr["BudgetCode"].ToString();
            if (string.IsNullOrEmpty(dr["EffectiveDate"].ToString()))
            {
                _para.EffectiveDate = GetEffectiveDate(_para).ToString();
            }
            else
            {
                _para.EffectiveDate = dr["EffectiveDate"].ToString();
            }

            _para.TaxGroupId = dr["TaxGroupIDSR"].ToString();
        }
        catch (Exception ex)
        {
            throw ex;
        }
