            DataView dv = null;
            DataView dvApproved = null;
            _NewFormula_Desc = string.Empty;
            _ApprovedFormula_Desc = string.Empty;
            //DataSet openHead = null;
            objApp = new clsEmployeeLoad();
            objApp.LoadEmployeeInfoForIncrementNew(_para, out dsLocal);
            if (dsLocal.Tables[0].Rows.Count > 0)
            {
                for (int i = 0; i < dsLocal.Tables[0].Rows.Count; i++)
                {
                    GetEmployeeInfo(dsLocal.Tables[0].Rows[i], _para);
                    //dv = CalculateSalary_From_OpenSalaryHeadValue(_para, out _NewFormula_Desc);
                    //dvApproved = CalculateSalary_From_ApprovedSalaryHeadValue(_para);

                }
                // kabir
                dsOpenHead = LoadOpenHead(_para);

                //dtCalculateSalary = dv.ToTable();
                //dtCalculateSalary = null;
                //dtApprovedCalculateSalary = dtCalculateSalary.ToTable();
                if (_para.IsFreshEntry == false)
                {
                    try
                    {
                        //CustomParaAdditionalPolicySetting para = null;
                        dv = CalculateSalary_From_OpenSalaryHeadValue(_para, out _NewFormula_Desc, out outpara);
                        dtCalculateSalary = dv.ToTable();

                    }
                    catch (Exception)
                    {

                        dtCalculateSalary = null;
                    }






                    //approved part
                    dsApprovedOpenHead = LoadApprovedOpenHead(_para);
                    GetMinWage(_para.PlantId, _para.EffectiveDate, _para.EmployeeId, out dsMinWage);
                    try
                    {


                        DataSet dsLastApprovedEffectiveDate = null;

                        GetLastApprovedEffectiveDate(_para.EmployeeId, out dsLastApprovedEffectiveDate);
                        if (dsLastApprovedEffectiveDate.Tables[0].Rows.Count > 0)
                        {
                            if (!string.IsNullOrEmpty(dsLastApprovedEffectiveDate.Tables[0].Rows[0]["EffectiveDate"].ToString()))
                            {
                                _para.EffectiveDate = dsLastApprovedEffectiveDate.Tables[0].Rows[0]["EffectiveDate"].ToString();
                                _para.SalaryRuleId = dsLastApprovedEffectiveDate.Tables[0].Rows[0]["SalaryRuleMasterSystemID"].ToString();
                            }
                        }


                        //StartCalculation(_para, dsApprovedOpenHead, out dtApprovedCalculateSalary, out _ApprovedFormula_Desc);
                        GetApprovedSalaryDetails(_para.PlantId, _para.EmployeeId, _para.EffectiveDate, out dtApprovedCalculateSalary);
                        LoadEmpSalaryInfoDefineData_OnGrid(_para, out _ApprovedFormula_Desc);
                    }
                    catch (Exception)
                    {

                        dtApprovedCalculateSalary = null;
                    }

                    //dtApprovedCalculateSalary = null;
                }
                else
                {


                    if (dsOpenHead.Tables[0].Rows.Count > 0)
                    {
                        DataView dvTemp = new DataView(dsOpenHead.Tables[0]);
                        dvTemp.RowFilter = "(HeadCategory='Basic' or HeadCategory='Gross') and Amount>0";
                        if (dvTemp.Count == 1)
                        {
                            dv = CalculateSalary_From_OpenSalaryHeadValue(_para, out _NewFormula_Desc, out outpara);
                        }
                        else
                        {

                            GetSalaryRuleFormula(_para, out _NewFormula_Desc, out _ApprovedFormula_Desc);
                        }

                    }
                    GetMinWage(_para.PlantId, _para.EffectiveDate, _para.EmployeeId, out dsMinWage);
                    dtApprovedCalculateSalary = null;
                    dsApprovedOpenHead = null;
                    dtCalculateSalary = null;

                }

            }
            else
            {
                throw new Exception("No employee found ..." + _para.EmployeeCode);
            }
        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            dsLocal = null;
        }
    }//End Function 
    public void StartCalculation(CustomParaNew _para, DataSet openHead, out DataTable dtResult, out string _Formula_Desc, out CustomParaAdditionalPolicySetting para)
    {
        para = null;
        DataSet dsLocal = null;
        clsEmployeeLoad objApp = null;
        _Formula_Desc = string.Empty;

        try
        {
            //lblImg.Text = "0";
            DataView dv = null;
            //DataSet openHead = null;
            objApp = new clsEmployeeLoad();
            objApp.LoadEmployeeInfoForIncrementNew(_para, out dsLocal);
            if (dsLocal.Tables[0].Rows.Count > 0)
            {
                for (int i = 0; i < dsLocal.Tables[0].Rows.Count; i++)
                {
                    GetEmployeeInfo(dsLocal.Tables[0].Rows[i], _para);
                    dv = CalculateSalary_From_NewOpenSalaryHeadValue(_para, openHead, out _Formula_Desc, out para);

                }
                // kabir
                dtResult = dv.ToTable();
            }
            else
            {
                throw new Exception("No employee found ...");
            }

        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            dsLocal = null;
        }
    }//End Function 
