    public void LoadSlrRuleInfo(CustomParaNew _para)
    {
        DataSet dsLocal = null;
        clsSalaryInfoForSalaryStructure objSal = null;

        StringCollection strCurrency = new StringCollection();

        string strCurrencyID = "";

        try
        {
            objSal = new clsSalaryInfoForSalaryStructure();

            Check("Plant", _para.PlantId);
            Check("SalaryRule", _para.SalaryRuleId);

            objSal.LoadSalaryRuleInfo(_para.PlantId, _para.SalaryRuleId, out dsLocal);

            if (dsLocal.Tables[0].Rows.Count > 0)
            {
                _para.SalaryRule = dsLocal.Tables[0].Rows[0]["SalaryRuleDescription"].ToString();

                for (int j = 0; j < dsLocal.Tables[0].Rows.Count; j++)
                {
                    if (strCurrency.Contains(dsLocal.Tables[0].Rows[j]["AmtEntryCurrency"].ToString().Trim()) == false)
                    {
                        strCurrency.Add(dsLocal.Tables[0].Rows[j]["AmtEntryCurrency"].ToString().Trim());
                    }
                    if (strCurrency.Contains(dsLocal.Tables[0].Rows[j]["AmtDefinitionCurrency"].ToString().Trim()) == false)
                    {
                        strCurrency.Add(dsLocal.Tables[0].Rows[j]["AmtDefinitionCurrency"].ToString().Trim());
                    }
                    if (strCurrency.Contains(dsLocal.Tables[0].Rows[j]["AmtDisbusmentCurrency"].ToString().Trim()) == false)
                    {
                        strCurrency.Add(dsLocal.Tables[0].Rows[j]["AmtDisbusmentCurrency"].ToString().Trim());
                    }
                }

                for (int c = 0; c < strCurrency.Count; c++)
                {
                    if (_para.LocalCurrencyId != strCurrency[c].ToString())
                    {
                        strCurrencyID = strCurrency[c].ToString();
                        _para.ForeignCurrencyId = strCurrency[c].ToString();
                    }
                }

                dsLocal = null;

                //objSal.GetCurrencyInfo((string)Session["LOGIN_GROUP_ID"].ToString().Trim(), ddlPlant.SelectedValue.ToString().Trim(), strCurrencyID, TextEffectiveDate.Text.Trim(), out dsLocal);
                objSal.GetCurrencyInfo(_para.CompanyGroupId, _para.PlantId, strCurrencyID, _para.EffectiveDate, out dsLocal);
                if (dsLocal.Tables[0].Rows.Count > 0)
                {
                    _para.ForeignCurrencyId = dsLocal.Tables[0].Rows[0]["CurrencyCode"].ToString().Trim();
                    // lblForeignCurrency.Text = "" + dsLocal.Tables[0].Rows[0]["CurrencyDesc"].ToString().Trim();
                    _para.ForeignCurRate = dsLocal.Tables[0].Rows[0]["ExchangeRate"].ToString().Trim();
                }
            }
            else
            {
                _para.ForeignCurrencyId = string.Empty;
                _para.ForeignCurRate = string.Empty;
            }
        }
        catch (Exception ex)
        {
            throw ex;
        }
        finally
        {
            objSal = null;
            dsLocal = null;
        }
    }//End Function

    private DataSet LoadOpenHead(CustomParaNew _para)
    {
        DataSet dsLocal = null;
        DataView dvLocal = null;
        DataRow drLocal = null;
        clsSalaryInfoForSalaryStructure objSal = null;

        try
        {
            objSal = new clsSalaryInfoForSalaryStructure();
            if (_para.IsFreshEntry == false)
            {
                Check("Effective Date", _para.EffectiveDate);

            }

            //objSal.SalaryOpenHeadOnGrid(ddlPlant.SelectedValue.ToString().Trim(), ddSalaryRule.SelectedValue.ToString().Trim(), lblEmpSystemId.Text.Trim(), TextEffectiveDate.Text.Trim(), out dsLocal);
            objSal.SalaryOpenHeadOnGrid(_para.PlantId, _para.SalaryRuleId, _para.EmployeeId, _para.EffectiveDate, out dsLocal);
            dvLocal = new DataView();
            dvLocal.Table = dsLocal.Tables[0];
            if (dsLocal.Tables[0].Rows.Count > 0)
            {
                dvLocal.RowFilter = "HeadCategory = 'Tax'";
                if (dvLocal.Count == 1)
                {
                    //this.lblMonthlyTaxPayableAmtEntryLabel.Visible = true;
                    //this.txtTaxToBePay.Visible = true;

                    drLocal = dvLocal[0].Row;
                    drLocal.Delete();
                }
                else
                {
                    //this.lblMonthlyTaxPayableAmtEntryLabel.Visible = false;
                    //this.txtTaxToBePay.Visible = false;
                }

                if (dsLocal.Tables[0].Rows[0]["EffectiveDate"].ToString().Trim() != "")
                {
                    _para.EffectiveDate = Convert.ToDateTime(dsLocal.Tables[0].Rows[0]["EffectiveDate"].ToString().Trim()).ToString("dd-MMM-yyyy");
                }
                //else
                //{
                //    this.TextEffectiveDate.Text = FirstDayOfNextMonthFromDateTime(System.DateTime.Now).ToString("dd-MMM-yyyy");
                //}
                // this.lblSalaryID.Text = dsLocal.Tables[0].Rows[0]["SalaryID"].ToString().Trim();

                //by monir
                DataSet dsSalary = null;
                objSal.GetSalaryID(_para.PlantId, _para.SalaryRuleId, _para.EmployeeId, _para.EffectiveDate, out dsSalary);
                if (dsSalary.Tables[0].Rows.Count > 0)
                {
                    _para.SalaryId = dsSalary.Tables[0].Rows[0]["SystemID"].ToString().Trim();
                }
            }
            else
            {
            }
            return dsLocal;
        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            objSal = null;
            dsLocal = null;
        }
    }//End Function 
