    private DataSet xLoadEmpSalaryInfoDefineData_OnGrid(CustomPara _para)
    {
        DataSet dsLocal = null;
        clsSalaryInfoForSalaryStructure objSal = null;
        bool bIsApproved = false;
        string _Formula_Desc = string.Empty;
        try
        {
            objSal = new clsSalaryInfoForSalaryStructure();
            //objSal.SalaryStructureAPHeadOnGrid(ddlPlant.SelectedValue.ToString().Trim(), lblEmpSystemId.Text.Trim(), lblStartmonth.Text, lblEndmonth.Text, TextEffectiveDate.Text, ddSalaryRule.SelectedValue, out dsLocal);
            objSal.SalaryStructureAPHeadOnGrid(_para.PlantId, _para.EmployeeId, _para.StartMonth, _para.EndMonth, _para.EffectiveDate, _para.SalaryRuleId, out dsLocal);
            if (dsLocal.Tables[0].Rows.Count > 0)
            {
                for (int i = 0; i < dsLocal.Tables[0].Rows.Count; i++)
                {
                    if (Convert.ToBoolean(dsLocal.Tables[0].Rows[i]["IsOpen"]) == false)
                    {
                        if (Convert.ToDecimal(dsLocal.Tables[0].Rows[i]["FixedValue"].ToString()) > 0)
                        {
                            _Formula_Desc += "\n" + dsLocal.Tables[0].Rows[i]["SalaryHead"].ToString() + ": " + dsLocal.Tables[0].Rows[i]["FixedValue"].ToString();
                        }
                        else if (dsLocal.Tables[0].Rows[i]["FormulaDes"].ToString() != "")
                        {
                            _Formula_Desc += "\n" + dsLocal.Tables[0].Rows[i]["SalaryHead"].ToString() + ": " + dsLocal.Tables[0].Rows[i]["FormulaDes"].ToString();
                        }
                    }

                    if (bIsApproved == false)
                    {
                        bIsApproved = Convert.ToBoolean(dsLocal.Tables[0].Rows[i]["IsApproved"]);
                    }
                }

                if (bIsApproved == true)
                {
                    _para.ApprovalStatus = HRApprovalStatus.Approved.ToString();
                }
                else
                {
                    _para.ApprovalStatus = HRApprovalStatus.Unapproved.ToString();
                }
            }
            else
            {
                _para.ApprovalStatus = HRApprovalStatus.Unapproved.ToString();
            }
            //}


            return dsLocal;
        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            objSal = null;
            dsLocal = null;
        }
    }//End Function 
