    private void CalculateSalary_EmpSalaryDefine(CustomParaNew _para, out string _Formula_Desc, out CustomParaAdditionalPolicySetting para)
    {
        para = null;
        DataSet dsLocal = null;
        DataSet dsOpenVal = null;
        DataView dvOpenValFil = null;
        DataSet dsSalHd = null;
        DataTable dtSalHd = null;
        //DataTable dtSlrHd = null;
        DataView dv = null;
        clsSalaryInfoNew objsi = null;
        DataSet dsMBAllowance = null;
        DataSet dsEntityAllowance = null;
        DataSet dsSlrFor = null;
        clsSalaryStructureAplos obSSa = new global::clsSalaryStructureAplos();
        clsSalaryUtility obSS = new global::clsSalaryUtility();

        try

        {
            Check("EmployeeId", _para.EmployeeId);
            //LoadSlrRuleInfo(_para);//add  for currancy id
            objsi = new clsSalaryInfoNew();
            if (string.IsNullOrEmpty(_para.ForeignCurRate) == true)
            {
                _para.ForeignCurRate = "0.0";
            }

            if (_para.ForeignCurRate.Length > 20 || bplib.clsWebLib.IsNumeric(_para.ForeignCurRate) == false)
            {
                Exception ex = new Exception("Invalid / Blank Data not allowed for 'Amount Definition Currency Rate'. \n Please Enter Numeric data Only");
                throw (ex);
            }

            if (bplib.clsWebLib.IsDateOK(_para.EffectiveDate) == false)
            {
                Exception ex = new Exception(bplib.clsWebLib.DateValidationMsg("Effective Date"));
                throw (ex);
            }

            //no past data
            DataSet dsMaxDate = null;
            objsi.GetMaxEffectiveDate(_para.EmployeeId, out dsMaxDate);//Salary Structure
            if (dsMaxDate.Tables[0].Rows.Count > 0)
            {
                if (Convert.ToDateTime(dsMaxDate.Tables[0].Rows[0]["EffectiveDate"].ToString()) > Convert.ToDateTime(_para.EffectiveDate))
                {
                    bplib.clsWebLib.Throw("Previous Data can not be inserted");
                }
            }

            ///180307
            objsi.GetMaxEffectiveDateProcessed(_para.EmployeeId, out dsMaxDate);//Processed Data
            if (dsMaxDate.Tables[0].Rows.Count > 0)
            {
                if (string.IsNullOrEmpty(dsMaxDate.Tables[0].Rows[0]["EffectiveDate"].ToString()))//no salary processed
                {
                    //bplib.clsWebLib.Throw(" " + FieldName + " can not be blank for Plant [" + ddlPlant.Items[ddlPlant.SelectedIndex].Text + "] ");
                }
                else
                {
                    if (Convert.ToDateTime(dsMaxDate.Tables[0].Rows[0]["EffectiveDate"].ToString()) > Convert.ToDateTime(_para.EffectiveDate))
                    {
                        bplib.clsWebLib.Throw("Salary has already been processed to Date [" + dsMaxDate.Tables[0].Rows[0]["EffectiveDate"].ToString() + "]");
                    }
                }
            }

            //LoadDataSetFromDataGrid(ref dgEmpSalaryDefine, out dsLocal);
            //LoadEmpSalaryInfoDefineData_OnGrid(out dsLocal);
            dsLocal = LoadEmpSalaryInfoDefineData_OnGrid(_para, out _Formula_Desc);//kkk

