    private void UpdateSalaryDefineDataRowForGrid(/*bool bIsSelectSlrHd, */string plantid, string emppk, string effectivedate, string SlrInfoDefSystemID, string CurrencyRuleChildSystemID, string SalaryHeadID, string SalaryHead, string HeadCategory, string HeadType, string FormulaDesID, string FixedValue, bool IsOpen, bool IsNA, string EntryCurrencyID, string EntryCurrency, string DefinitionCurrencyID, string DefinitionCurrency, string EntryAmount, string DefineAmount/*, bool TagAndUnTag*/, string MonthPeriod, bool BaseOnNetPay, bool RefAbsentism,/* bool IsCTCComponent, bool IsGrossComponent,*/ bool IsGNRBaseOthSlrHD, string GNRBaseOthSlrHDFormula, string GNRApplicableMonthNo, string EarningCurrencyID, string EarningAmount, int SrNoTPG, bool IsGNRWhichEverLess, string sRoundOption, bool bIntegerInDisb, bool bIsDecimalInDisb, int iDecimalNo, string sSalaryCategory, int iSalaryHdSequence, bool IsSlabBased, ref DataRow drLocal)
    {
        clsSalaryUtility obSS = new global::clsSalaryUtility();
        //clsSalaryStructureAplos obSS = new global::clsSalaryStructureAplos();
        try
        {
            if (HeadType == "E")
            { HeadType = "Earning"; }
            else if (HeadType == "D")
            { HeadType = "Deduction"; }
            //drLocal["IsSelectSlrHd"] = bIsSelectSlrHd;
            drLocal["SlrInfoDefSystemID"] = SlrInfoDefSystemID;
            drLocal["CurrencyRuleChildSystemID"] = CurrencyRuleChildSystemID;
            drLocal["SalaryHeadID"] = SalaryHeadID;
            drLocal["SalaryHead"] = SalaryHead;
            drLocal["HeadCategory"] = HeadCategory;
            drLocal["HeadType"] = HeadType;
            drLocal["FormulaDesID"] = FormulaDesID;
            drLocal["FixedValue"] = FixedValue;
            drLocal["IsOpen"] = IsOpen;
            drLocal["IsNA"] = IsNA;
            drLocal["EntryCurrencyID"] = EntryCurrencyID;
            drLocal["EntryCurrency"] = EntryCurrency;
            drLocal["DefinitionCurrencyID"] = DefinitionCurrencyID;
            drLocal["DefinitionCurrency"] = DefinitionCurrency;

            string sOutEntryAmt = "";
            string sOutDefineAmt = "";
            obSS.FractionCalculation(sRoundOption, bIntegerInDisb, bIsDecimalInDisb, iDecimalNo, EntryAmount, out sOutEntryAmt);
            obSS.FractionCalculation(sRoundOption, bIntegerInDisb, bIsDecimalInDisb, iDecimalNo, DefineAmount, out sOutDefineAmt);

            drLocal["EntryAmount"] = sOutEntryAmt;
            drLocal["DefineAmount"] = sOutDefineAmt;
            //drLocal["EntryAmount"] = EntryAmount;
            //drLocal["DefineAmount"] = DefineAmount;

            //drLocal["TagAndUnTag"] = TagAndUnTag;
            drLocal["MonthPeriod"] = MonthPeriod;

            drLocal["BaseOnNetPay"] = BaseOnNetPay;
            drLocal["RefAbsentism"] = RefAbsentism;
            //drLocal["IsCTCComponent"] = IsCTCComponent;
            //drLocal["IsGrossComponent"] = IsGrossComponent;
