            //drLocal["EmpSystemID"] = lblEmpSystemId.Text.Trim();
            //drLocal["EffectiveDate"] = Convert.ToDateTime(this.TextEffectiveDate.Text.Trim());

            drLocal["PlantID"] = plantid;
            drLocal["EmpSystemID"] = emppk;
            drLocal["EffectiveDate"] = Convert.ToDateTime(effectivedate);

            drLocal["SalaryRuleMasterSystemID"] = "";
            drLocal["IsMonthDay"] = false;
            drLocal["IsMonthWorkDay"] = false;
            drLocal["IsFixedDisbus"] = false;
            drLocal["IsBankPayment"] = false;
            drLocal["IsCashPayment"] = false;
            drLocal["cumulateExchangeRate"] = false;
            drLocal["AmtDefinitionCurrencyID"] = DefinitionCurrencyID;
            drLocal["AmtDefinitionRate"] = 1;
            drLocal["DefineCurrencyID"] = DefinitionCurrency;
            drLocal["SalaryID"] = "";
            drLocal["AccumulateExchangeRate"] = false;
            drLocal["AcltExcDisbSlrHDID"] = "";
            drLocal["DisbusmentCurrencyID"] = "";
            drLocal["DisbusmentCurrency"] = "";
            drLocal["RuleType"] = "";
            drLocal["FixedMonthDayValue"] = 0;
            drLocal["SalaryRuleDayStatusSystemID"] = "";
            drLocal["IsOverWrite"] = false;
            drLocal["ShiftType"] = "";
            drLocal["DayType"] = "";
            drLocal["LeaveType"] = "";
            drLocal["IsNetPayEffect"] = false;

            drLocal["RoundOption"] = sRoundOption;
            drLocal["IntegerInDisb"] = bIntegerInDisb;
            drLocal["IsDecimalInDisb"] = bIsDecimalInDisb;
            drLocal["DecimalNo"] = iDecimalNo;
            drLocal["SalaryCategory"] = sSalaryCategory;
            drLocal["SalaryHdSequence"] = iSalaryHdSequence;
            drLocal["IsSlabBased"] = IsSlabBased;

        }
