    public DateTime FirstDayOfNextMonthFromDateTime(DateTime dateTime)
    {
        DateTime firstDayOfTheNextMonth = new DateTime(dateTime.Year, dateTime.Month, 1);
        return firstDayOfTheNextMonth.AddMonths(1);
    }//end function
