    public void GetPFMonthlyDistributionEmployeeForSalaryStrac(string sPFMntEmpWiseCalID, DataTable stable, out DataTable dtPFMntDisEmp)
    {
        List<SSPFTemp1> olist1 = new List<SSPFTemp1>();
        List<SSPFTemp1> olist2 = new List<SSPFTemp1>();

        DataRow drPFMntDisEmp = null;
        DataView dvPFMntDisEmp = null;
        dtPFMntDisEmp = new DataTable();
        dtPFMntDisEmp.TableName = "TempTable";
        dtPFMntDisEmp.Columns.Add("PFMntEmpWiseCalID");
        dtPFMntDisEmp.Columns.Add("SalaryHeadID");
        dtPFMntDisEmp.Columns.Add("Amount");



        dvPFMntDisEmp = new DataView();
        dvPFMntDisEmp.Table = dtPFMntDisEmp;

        //dvPFMntDisEmp.RowFilter = "PFEligibleEmpID = '" + sPFEligibleEmpID + "' AND MonthNo = '" + Convert.ToDateTime(para.ToDate).Month + "' AND YearNo = '" + Convert.ToDateTime(para.ToDate).Year + "'";
        //if (dvPFMntDisEmp.Count == 0)
        //{//Add new block
        //    drPFMntDisEmp = dtPFMntDisEmp.NewRow();
        //    drPFMntDisEmp["PFMntEmpWiseCalID"] = "";
        //    drPFMntDisEmp["SalaryHeadID"] = "";
        //    drPFMntDisEmp["Amount"] = "";
        //    dtPFMntDisEmp.Rows.Add(drPFMntDisEmp);
        //}



        try
        {
            //var salarydistinctHeadIds = stable.AsEnumerable()
            //          .Where(y => y.Field<string>("PFMntEmpWiseCalID") == sPFMntEmpWiseCalID)
            //          .Select(s => new
            //          {
            //              id = s.Field<string>("SalaryHeadID")
            //          })
            //          .Distinct().ToList();
            List<string> salarydistinctHeadIds = (from row in stable.AsEnumerable()
                                                  where row.Field<string>("PFMntEmpWiseCalID") == sPFMntEmpWiseCalID && row.Field<string>("PFMntEmpWiseCalID") != " "
                                                  select row.Field<string>("SalaryHeadID")).Distinct().ToList();
            foreach (var item in salarydistinctHeadIds)
            {
                if (!string.IsNullOrEmpty(item))
                {
                    SSPFTemp1 o = new SSPFTemp1();
                    var re = stable.Compute("SUM([Value])", "ISNULL(SalaryHeadID, '') = '" + item + "' AND [Value] > 0 AND PFMntEmpWiseCalID = '" + sPFMntEmpWiseCalID + "'").ToString();

                    var sub = olist1.FindAll(x => x.SalaryHeadID == item.ToString() && x.PFMntEmpWiseCalID == sPFMntEmpWiseCalID.ToString());
                    if (sub.Count > 0)
                    {
                        decimal oba = 0;
                        decimal obr = 0;
                        var ob = sub[0];
                        if (!string.IsNullOrEmpty(ob.Amount))
                        {
                            oba = Convert.ToDecimal(ob.Amount);
                        }
                        if (!string.IsNullOrEmpty(re))
                        {
                            obr = Convert.ToDecimal(re);
                        }
                        ob.Amount = (oba + obr).ToString();
                    }
                    else
                    {
                        o.Amount = re.ToString();
                        o.SalaryHeadID = item.ToString();
                        o.PFMntEmpWiseCalID = sPFMntEmpWiseCalID.ToString();
                        olist1.Add(o);
                    }

                }
            }


            List<string> distinctResidualValueSlrHdID = (from row in stable.AsEnumerable()
                                                         where row.Field<string>("PFMntEmpWiseCalID") == sPFMntEmpWiseCalID && row.Field<string>("PFMntEmpWiseCalID") != " "
                                                         select row.Field<string>("ResidualValueSlrHdID")).Distinct().ToList();


            foreach (var item in distinctResidualValueSlrHdID)
            {
                if (!string.IsNullOrEmpty(item))
                {
                    SSPFTemp1 o = new SSPFTemp1();
                    var re = stable.Compute("SUM([UpperLimit])", "ISNULL(ResidualValueSlrHdID, '') = '" + item + "' AND [UpperLimit] > 0 AND PFMntEmpWiseCalID = '" + sPFMntEmpWiseCalID + "'").ToString();
                    //o.Amount = re.ToString();
                    //o.SalaryHeadID = item.ToString();
                    //o.PFMntEmpWiseCalID = sPFMntEmpWiseCalID.ToString();
                    //olist1.Add(o);

                    var sub = olist1.FindAll(x => x.SalaryHeadID == item.ToString() && x.PFMntEmpWiseCalID == sPFMntEmpWiseCalID.ToString());
                    if (sub.Count > 0)
                    {
                        decimal oba = 0;
                        decimal obr = 0;
                        var ob = sub[0];
                        if (!string.IsNullOrEmpty(ob.Amount))
                        {
                            oba = Convert.ToDecimal(ob.Amount);
                        }
                        if (!string.IsNullOrEmpty(re))
                        {
                            obr = Convert.ToDecimal(re);
                        }
                        ob.Amount = (oba + obr).ToString();
                    }
                    else
                    {
                        o.Amount = re.ToString();
                        o.SalaryHeadID = item.ToString();
                        o.PFMntEmpWiseCalID = sPFMntEmpWiseCalID.ToString();
                        olist1.Add(o);
                    }
                }

            }


            foreach (SSPFTemp1 item in olist1)
            {
                if (!string.IsNullOrEmpty(item.Amount))
                {
                    drPFMntDisEmp = dtPFMntDisEmp.NewRow();
                    drPFMntDisEmp["PFMntEmpWiseCalID"] = item.PFMntEmpWiseCalID;
                    drPFMntDisEmp["SalaryHeadID"] = item.SalaryHeadID;
                    drPFMntDisEmp["Amount"] = item.Amount;
                    dtPFMntDisEmp.Rows.Add(drPFMntDisEmp);
                }

            }
        }
        catch (Exception ex)
        {

            throw ex;
        }

    }



