    public void ValidationbySalaryRule(string SalaryRuleId, ref DataTable dt)
    {
        DataSet SalaryRuleDetails = null;
        GetSalaryValidationByRule(SalaryRuleId, out SalaryRuleDetails);
        if (SalaryRuleDetails.Tables[0].Rows.Count > 0)
        {
            for (int i = 0; i < SalaryRuleDetails.Tables[0].Rows.Count; i++)
            {
                DataView dv = new DataView();
                string HeadId = string.Empty;
                decimal MaxValue = 0;
                decimal MinValue = 0;
                //Has Max Limit
                if (bplib.clsWebLib.GetBoolData(SalaryRuleDetails.Tables[0].Rows[i]["HasMaxLimit"].ToString()) == true)
                {
                    HeadId = SalaryRuleDetails.Tables[0].Rows[i]["SalaryHeadID"].ToString();
                    //Fixed
                    if (bplib.clsWebLib.GetBoolData(SalaryRuleDetails.Tables[0].Rows[i]["FixedMaxLimit"].ToString()) == true)
                    {
                        if (!string.IsNullOrEmpty(SalaryRuleDetails.Tables[0].Rows[i]["MaxLimitValue"].ToString()))
                        {
                            MaxValue = Convert.ToDecimal(SalaryRuleDetails.Tables[0].Rows[i]["MaxLimitValue"].ToString());

                        }
                    }
                    //Percentage
                    if (bplib.clsWebLib.GetBoolData(SalaryRuleDetails.Tables[0].Rows[i]["PercentageMaxLimit"].ToString()) == true)
                    {
                        var Percentage = SalaryRuleDetails.Tables[0].Rows[i]["MaxLimitValue"].ToString();
                        var PercentageHeadID = SalaryRuleDetails.Tables[0].Rows[i]["PercentageMaxLimitSalaryHeadId"].ToString();
                        //dv = new DataView();
                        dv.Table = dt;
                        dv.RowFilter = "SalaryHeadID = '" + PercentageHeadID + "'";
                        //var value=dv.row
                        if (dv.Count > 0)
                        {
                            var EntryAmounts = dv[0]["EntryAmount"].ToString();
                            MaxValue = Convert.ToDecimal(EntryAmounts) * Convert.ToDecimal(Percentage) / 100;
                        }
                        else
                        {
                            // error
                        }
                        dv.RowFilter = null;
                    }



                }
                if (bplib.clsWebLib.GetBoolData(SalaryRuleDetails.Tables[0].Rows[i]["HasMinLimit"].ToString()) == true)
                {
                    HeadId = SalaryRuleDetails.Tables[0].Rows[i]["SalaryHeadID"].ToString();
                    //Fixed
                    if (bplib.clsWebLib.GetBoolData(SalaryRuleDetails.Tables[0].Rows[i]["FixedMinLimit"].ToString()) == true)
                    {
                        if (!string.IsNullOrEmpty(SalaryRuleDetails.Tables[0].Rows[i]["MinLimitValue"].ToString()))
                        {
                            MinValue = Convert.ToDecimal(SalaryRuleDetails.Tables[0].Rows[i]["MinLimitValue"].ToString());

                        }
                    }
                    //Percentage
                    if (bplib.clsWebLib.GetBoolData(SalaryRuleDetails.Tables[0].Rows[i]["PercentageMinLimit"].ToString()) == true)
                    {
                        var Percentage = SalaryRuleDetails.Tables[0].Rows[i]["MinLimitValue"].ToString();
                        var PercentageHeadID = SalaryRuleDetails.Tables[0].Rows[i]["PercentageMinLimitSalaryHeadId"].ToString();
                        //dv = new DataView();
                        dv.Table = dt;
                        dv.RowFilter = "SalaryHeadID = '" + PercentageHeadID + "'";
                        //var value=dv.row
                        if (dv.Count > 0)
                        {
                            var EntryAmounts = dv[0]["EntryAmount"].ToString();
                            MinValue = Convert.ToDecimal(EntryAmounts) * Convert.ToDecimal(Percentage) / 100;
                        }
                        else
                        {
                            // error
                        }
                        dv.RowFilter = null;
                    }
                }
                if (!string.IsNullOrEmpty(HeadId))
                {
                    DataRow drLocal = null;
                    dv.Table = dt;
                    dv.RowFilter = "SalaryHeadID = '" + HeadId + "'";
                    if (dv.Count > 0)
                    {
                        if (MaxValue > 0)
                        {

                            var EntryAmounts = dv[0]["EntryAmount"].ToString();
                            if (Convert.ToDecimal(EntryAmounts) > MaxValue)
                            {
                                drLocal = dv[0].Row;
                                drLocal.BeginEdit();
                                drLocal["EntryAmount"] = MaxValue;
                                drLocal["DefineAmount"] = MaxValue;
                                drLocal.EndEdit();
                            }

                        }
                        if (MinValue > 0)
                        {

                            var EntryAmounts = dv[0]["EntryAmount"].ToString();
                            if (Convert.ToDecimal(EntryAmounts) < MinValue)
                            {
                                drLocal = dv[0].Row;
                                drLocal.BeginEdit();
                                drLocal["EntryAmount"] = MinValue;
                                drLocal["DefineAmount"] = MinValue;
                                drLocal.EndEdit();
                            }

                        }
                        dv.RowFilter = null;
                    }

                }
            }
        }
    }

    public void GetAdditionalPolicySalaryID(string SalaryID, string EmpSystemID, out DataSet dsRef)
    {

        ConnectionManager.DAL.ConManager objCon;
        string strSql = "";
        try
        {
            strSql = @"SELECT * FROM EmployeeEligibleForSalaryHeadEnum WHERE SalaryStructureId ='" + SalaryID + @"' AND EmpSystemId ='" + EmpSystemID + @"'";


            objCon = new ConnectionManager.DAL.ConManager("1");
            objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, "1");

        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            objCon = null;
        }
    }//End Function


