                            dtRow["SalaryCategory"] = dsLocal.Tables[0].Rows[i]["SalaryCategory"].ToString().Trim();
                            //dt.Rows.Add(dtRow);
                        }
                        #endregion For NULL Value
                        dt.Rows.Add(dtRow);
                    }
                    #endregion

                }

                dv = new DataView();
                dv.Table = dt;
            }
            return dv;
        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
        }
    }//End Function 

