                            else if (IsGNRBaseOthSlrHD == true && IsGNRWhichEverLess == false)
                            {
                                #region Base On Other Salary Head

                                bBaseOthShdID = false;
                                if (Convert.ToBoolean(dsLocal.Tables[0].Rows[i]["IsGNRBaseOthSlrHD"].ToString().Trim()) == true)
                                {
                                    sGNRBaseOthSlrHDFormula = dsLocal.Tables[0].Rows[i]["GNRBaseOthSlrHDFormula"].ToString().Trim();
                                    obSS.dtIdList(sGNRBaseOthSlrHDFormula, out dsSlrFor);
                                    if (dsSlrFor.Tables[0].Rows.Count > 0)
                                    {
                                        sGNRBaseOthSlrHDFormula = dsSlrFor.Tables[0].Rows[0]["ID"].ToString().Trim();
                                        sBaseOthOperatorFor = dsSlrFor.Tables[0].Rows[1]["ID"].ToString().Trim();
                                        sGRNBaseOthVal = dsSlrFor.Tables[0].Rows[2]["ID"].ToString().Trim();
                                    }
                                    //ReLoadFormulaWithValue(sGNRBaseOthSlrHDFormula, ref dtValue);
                                    //sFormulaResult = Evaluate(lblFormulaValue.Text.Trim()).ToString();
                                    //obSS.ReLoadFormulaWithValue(sGNRBaseOthSlrHDFormula, ref dtValue, lblLocalCurrencyID.Text, txtForeignCurRate.Text, out _formulaValue, ref dtSlrHd);
                                    obSS.ReLoadFormulaWithValue(sGNRBaseOthSlrHDFormula, ref dtValue, _para.LocalCurrencyId, _para.ForeignCurRate, out _formulaValue, ref dtSalHd);
                                    //lblFormulaValue.Text = _formulaValue;
                                    _para.FormulaValue = _formulaValue;
                                    //sFormulaResult = clsSalaryStructureAplos.Evaluate(lblFormulaValue.Text.Trim()).ToString();
                                    sFormulaResult = clsSalaryStructureAplos.Evaluate(_para.FormulaValue).ToString();

                                    if (sBaseOthOperatorFor == "<")
                                    {
                                        if (Convert.ToDecimal(sFormulaResult.Trim()) < Convert.ToDecimal(sGRNBaseOthVal))
                                        {
                                            bBaseOthShdID = true;
                                        }
                                    }
                                    if (sBaseOthOperatorFor == ">")
                                    {
                                        //if (Convert.ToDecimal(lblFormulaValue.Text.Trim()) > Convert.ToDecimal(sGRNBaseOthVal))
                                        if (Convert.ToDecimal(_para.FormulaValue) > Convert.ToDecimal(sGRNBaseOthVal))
                                        {
                                            bBaseOthShdID = true;
                                        }
                                    }
                                    if (sBaseOthOperatorFor == "=")
                                    {
                                        //if (Convert.ToDecimal(lblFormulaValue.Text.Trim()) == Convert.ToDecimal(sGRNBaseOthVal))
                                        if (Convert.ToDecimal(_para.FormulaValue) == Convert.ToDecimal(sGRNBaseOthVal))
                                        {
                                            bBaseOthShdID = true;
                                        }
                                    }
                                    if (bBaseOthShdID == true)
                                    {
                                        #region For Formula Value
                                        if (string.IsNullOrEmpty(dsLocal.Tables[0].Rows[i]["FormulaDesID"].ToString().Trim()) == false)
                                        {
                                            dtRow["IsSelectSlrHd"] = Convert.ToBoolean(dsLocal.Tables[0].Rows[i]["IsSelectSlrHd"].ToString().Trim());
                                            dtRow["SlrInfoDefSystemID"] = dsLocal.Tables[0].Rows[i]["SlrInfoDefSystemID"].ToString().Trim();
                                            dtRow["CurrencyRuleChildSystemID"] = dsLocal.Tables[0].Rows[i]["CurrencyRuleChildSystemID"].ToString().Trim();
                                            dtRow["SalaryHeadID"] = dsLocal.Tables[0].Rows[i]["SalaryHeadID"].ToString().Trim();
                                            dtRow["SalaryHead"] = dsLocal.Tables[0].Rows[i]["SalaryHead"].ToString().Trim();
                                            dtRow["HeadType"] = dsLocal.Tables[0].Rows[i]["HeadType"].ToString().Trim();
                                            dtRow["FormulaDesID"] = dsLocal.Tables[0].Rows[i]["FormulaDesID"].ToString().Trim();
                                            dtRow["FixedValue"] = dsLocal.Tables[0].Rows[i]["FixedValue"].ToString().Trim();
                                            dtRow["IsOpen"] = Convert.ToBoolean(dsLocal.Tables[0].Rows[i]["IsOpen"].ToString().Trim());
                                            dtRow["IsNA"] = Convert.ToBoolean(dsLocal.Tables[0].Rows[i]["IsNA"].ToString().Trim());
                                            dtRow["EntryCurrencyID"] = dsLocal.Tables[0].Rows[i]["EntryCurrencyID"].ToString().Trim();
                                            dtRow["EntryCurrency"] = dsLocal.Tables[0].Rows[i]["EntryCurrency"].ToString().Trim();
                                            dtRow["DefinitionCurrencyID"] = dsLocal.Tables[0].Rows[i]["DefinitionCurrencyID"].ToString().Trim();
                                            dtRow["DefinitionCurrency"] = dsLocal.Tables[0].Rows[i]["DefinitionCurrency"].ToString().Trim();
                                            dtRow["HeadCategory"] = dsLocal.Tables[0].Rows[i]["HeadCategory"].ToString().Trim();

                                            sFormulaID = dsLocal.Tables[0].Rows[i]["FormulaDesID"].ToString().Trim();

                                            //ReLoadFormulaWithValue(sFormulaID, ref dtValue);
                                            //sFormulaResult = Evaluate(lblFormulaValue.Text.Trim()).ToString();
                                            //obSS.ReLoadFormulaWithValue(sFormulaID, ref dtValue, lblLocalCurrencyID.Text, txtForeignCurRate.Text, out _formulaValue, ref dtSlrHd);
                                            obSS.ReLoadFormulaWithValue(sFormulaID, ref dtValue, _para.LocalCurrencyId, _para.ForeignCurRate, out _formulaValue, ref dtSalHd);
                                            //lblFormulaValue.Text = _formulaValue;
                                            _para.FormulaValue = _formulaValue;
                                            //sFormulaResult = clsSalaryStructureAplos.Evaluate(lblFormulaValue.Text.Trim()).ToString();
                                            sFormulaResult = clsSalaryStructureAplos.Evaluate(_para.FormulaValue).ToString();

                                            //if (dsLocal.Tables[0].Rows[i]["EntryCurrencyID"].ToString().Trim() == lblLocalCurrencyID.Text.Trim())
                                            if (dsLocal.Tables[0].Rows[i]["EntryCurrencyID"].ToString().Trim() == _para.LocalCurrencyId)
                                            {
                                                sFormulaResultEnt = sFormulaResult;
                                            }
                                            else
                                            {
                                                //sFormulaResultEnt = (Convert.ToDecimal(sFormulaResult) / Convert.ToDecimal(txtForeignCurRate.Text)).ToString();
                                                sFormulaResultEnt = (Convert.ToDecimal(sFormulaResult) / Convert.ToDecimal(_para.ForeignCurRate)).ToString();
                                            }

                                            if (Convert.ToDecimal(sFormulaResultEnt) < 0)
                                            {
                                                throw new Exception("'Open value' must be increased...otherwise [" + dsLocal.Tables[0].Rows[i]["SalaryHead"].ToString().Trim() + "] would be negetive (" + Convert.ToDecimal(sFormulaResultEnt).ToString(_FORMAT_DECIMAL_2) + ")...");
                                            }

                                            sOutEntryAmt = "";
                                            obSS.FractionCalculation(sRoundOption, bIntegerInDisb, bIsDecimalInDisb, iDecimalNo, sFormulaResultEnt, out sOutEntryAmt);
                                            //dtRow["EntryAmount"] = Convert.ToDecimal(sFormulaResultEnt).ToString(_FORMAT_DECIMAL_2);

                                            //if (dsLocal.Tables[0].Rows[i]["DefinitionCurrencyID"].ToString().Trim() == lblLocalCurrencyID.Text.Trim())
                                            if (dsLocal.Tables[0].Rows[i]["DefinitionCurrencyID"].ToString().Trim() == _para.LocalCurrencyId)
                                            {
                                                sFormulaResultDef = sFormulaResult;
                                            }
                                            else
                                            {
                                                //sFormulaResultDef = (Convert.ToDecimal(sFormulaResult) / Convert.ToDecimal(txtForeignCurRate.Text)).ToString();
                                                sFormulaResultDef = (Convert.ToDecimal(sFormulaResult) / Convert.ToDecimal(_para.ForeignCurRate)).ToString();
                                            }

                                            sOutDefineAmt = "";
                                            obSS.FractionCalculation(sRoundOption, bIntegerInDisb, bIsDecimalInDisb, iDecimalNo, sFormulaResultDef, out sOutDefineAmt);
                                            //dtRow["DefineAmount"] = Convert.ToDecimal(sFormulaResultDef).ToString(_FORMAT_DECIMAL_2);

                                            dtRow["EntryAmount"] = sOutEntryAmt;
                                            dtRow["DefineAmount"] = sOutDefineAmt;

                                            //dtRow["TagAndUnTag"] = dsLocal.Tables[0].Rows[i]["TagAndUnTag"].ToString().Trim();
                                            dtRow["MonthPeriod"] = dsLocal.Tables[0].Rows[i]["MonthPeriod"].ToString().Trim();

                                            #region For SalaryHead Wise Amount In Virtual 2nd Table

                                            DataRow dtValueRow = dtValue.NewRow();

                                            dtValueRow["SalaryHeadID"] = dsLocal.Tables[0].Rows[i]["SalaryHeadID"].ToString().Trim();
                                            dtValueRow["EntryCurrencyID"] = dsLocal.Tables[0].Rows[i]["EntryCurrencyID"].ToString().Trim();
                                            dtValueRow["Amount"] = sFormulaResultEnt;

                                            dtValue.Rows.Add(dtValueRow);

                                            #endregion For SalaryHead Wise Amount In Virtual 2nd Table

                                            dtRow["BaseOnNetPay"] = dsLocal.Tables[0].Rows[i]["BaseOnNetPay"].ToString().Trim();
                                            dtRow["RefAbsentism"] = dsLocal.Tables[0].Rows[i]["RefAbsentism"].ToString().Trim();
                                            //dtRow["IsCTCComponent"] = dsLocal.Tables[0].Rows[i]["IsCTCComponent"].ToString().Trim();
                                            //dtRow["IsGrossComponent"] = dsLocal.Tables[0].Rows[i]["IsGrossComponent"].ToString().Trim();
                                            dtRow["IsGNRBaseOthSlrHD"] = dsLocal.Tables[0].Rows[i]["IsGNRBaseOthSlrHD"].ToString().Trim();
                                            dtRow["GNRBaseOthSlrHDFormula"] = dsLocal.Tables[0].Rows[i]["GNRBaseOthSlrHDFormula"].ToString().Trim();
                                            dtRow["GNRApplicableMonthNo"] = dsLocal.Tables[0].Rows[i]["GNRApplicableMonthNo"].ToString().Trim();
                                            dtRow["EarningCurrencyID"] = dsLocal.Tables[0].Rows[i]["EarningCurrencyID"].ToString().Trim();
                                            dtRow["EarningAmount"] = dsLocal.Tables[0].Rows[i]["EarningAmount"].ToString().Trim();
                                            dtRow["SequenceNo"] = clsStaticInfo.dbl(dsLocal.Tables[0].Rows[i]["SequenceNo"].ToString().Trim());
                                            dtRow["IsGNRWhichEverLess"] = Convert.ToBoolean(dsLocal.Tables[0].Rows[i]["IsGNRWhichEverLess"].ToString().Trim());

                                            dtRow["RoundOption"] = sRoundOption;
                                            dtRow["IntegerInDisb"] = bIntegerInDisb;
                                            dtRow["IsDecimalInDisb"] = bIsDecimalInDisb;
                                            dtRow["DecimalNo"] = iDecimalNo;
                                            dtRow["SalaryCategory"] = dsLocal.Tables[0].Rows[i]["SalaryCategory"].ToString().Trim();
                                            dtRow["SalaryHdSequence"] = dsLocal.Tables[0].Rows[i]["SalaryHdSequence"].ToString().Trim();
                                            dtRow["IsSlabBased"] = Convert.ToBoolean(dsLocal.Tables[0].Rows[i]["IsSlabBased"].ToString().Trim());
                                        }
                                        #endregion For Formula Value
                                    }
                                }

                                #endregion Base On Other Salary Head
                            }

                            else if (IsGNRBaseOthSlrHD == false && IsGNRWhichEverLess == true)
                            {
                                #region Which Ever IS Less
