    void GetSlabValue(string SalaryHead, DataSet dsSalabValue, DataTable dtValue, out decimal Amount)
    {
        Amount = 0;
        try
        {
            DataView dv = new DataView(dsSalabValue.Tables[0]);
            dv.RowFilter = "ValueSalaryHeadId='" + SalaryHead + "'";
            if (dv.Count > 0)
            {
                string BaseSalaryHeadId = dv[0]["BaseSalaryHeadId"].ToString();

                DataView dvValue = new DataView(dtValue);
                dvValue.RowFilter = "SalaryHeadId='" + BaseSalaryHeadId + "'";
                if (dvValue.Count > 0)
                {
                    string Amounts = dvValue[0]["Amount"].ToString();

                    dv.RowFilter = "ValueSalaryHeadId='" + SalaryHead + "' and BaseSalaryHeadId='" + BaseSalaryHeadId + "' AND BaseSalaryHeadMinAmount<= " + Amounts + " AND BaseSalaryHeadMaxAmount>=" + Amounts;
                    if (dv.Count > 0)
                    {
                        Amount = Convert.ToDecimal(dv[0]["ValueSalaryHeadAmount"].ToString());
                    }

                }
            }

        }
        catch (Exception ex)
        {

            throw ex;
        }

    }


