    private void GetAmountHeadCategoryWise(string SalaryID, string HeadCategory, DataSet dsEntityAllowance, DataSet dsMBallowance, DataSet dsSalaryHeadId, DataSet dsCTCAmount, out string _allowance, out string _currency)
    {
        //SalaryRuleName
        DataSet dsTotalSalaryID = null;
        _allowance = string.Empty;
        _currency = string.Empty;
        string _totaSalaryID = string.Empty;

        GetTotalSalaryID(SalaryID, out dsTotalSalaryID);
        if (dsTotalSalaryID.Tables[0].Rows.Count > 0)
        {
            _totaSalaryID = dsTotalSalaryID.Tables[0].Rows[0]["TotalSalaryId"].ToString();
        }

        if (_totaSalaryID.Length == 0)
        {
            if (dsTotalSalaryID.Tables[0].Rows.Count > 0)
            {
                bplib.clsWebLib.Throw("Salary Rule [" + dsTotalSalaryID.Tables[0].Rows[0]["SalaryRuleName"].ToString() + "] has no Total salary amount.");

            }

        }

        try
        {
            if (HeadCategory == "Skill Allowance")
            {
                if (dsMBallowance.Tables[0].Rows.Count > 0)
                {
                    // _allowance = Convert.ToDecimal(dsMBallowance.Tables[0].Rows[0]["SkillAllowance"].ToString());
                    _allowance = dsMBallowance.Tables[0].Rows[0]["SkillAllowance"].ToString();
                    _currency = (dsMBallowance.Tables[0].Rows[0]["CurrencyId"].ToString());
                }
            }
            else if (HeadCategory == "Responsibility Allowance")
            {
                if (dsMBallowance.Tables[0].Rows.Count > 0)
                {
                    //_allowance = Convert.ToDecimal(dsMBallowance.Tables[0].Rows[0]["ResponsibilityAllowance"].ToString());
                    _allowance = dsMBallowance.Tables[0].Rows[0]["ResponsibilityAllowance"].ToString();
                    _currency = (dsMBallowance.Tables[0].Rows[0]["CurrencyId"].ToString());
                }
            }
            else if (HeadCategory == "Special Allowance")
            {
                if (dsMBallowance.Tables[0].Rows.Count > 0)
                {
                    decimal _ctc = 0;
                    DataView dv = new DataView(dsSalaryHeadId.Tables[0]);
                    dv.RowFilter = "SalaryHeadID='" + _totaSalaryID + "'";
                    if (dv.Count > 0)
                    {
                        string headid = dv[0]["SalaryHeadID"].ToString();


                        DataView dva = new DataView(dsCTCAmount.Tables[0]);
                        dva.RowFilter = "SalaryHeadID='" + headid + "'";
                        if (dva.Count > 0)
                        {
                            _ctc = Convert.ToDecimal(dva[0]["Amount"]);
                        }
                    }

                    ///ctc-maxSal-3allowance
                    //_allowance = Convert.ToDecimal(dsMBallowance.Tables[0].Rows[0]["MaximumSalary"].ToString());
                    decimal maxv = Convert.ToDecimal(dsMBallowance.Tables[0].Rows[0]["MaximumSalary"].ToString());
                    if (maxv > 0)
                    {


                        decimal vv = _ctc - maxv;
                        if (vv > 0)
                        {
                            _allowance = vv.ToString(_FORMAT_DECIMAL_2);
                        }
                        else
                        {
                            _allowance = "0.00";
                        }
                        _currency = (dsMBallowance.Tables[0].Rows[0]["CurrencyId"].ToString());
                    }//maxv
                }
            }
            else if (HeadCategory == "Location Allowance")
            {
                if (dsEntityAllowance.Tables[0].Rows.Count > 0)
                {
                    //_allowance = Convert.ToDecimal(dsEntityAllowance.Tables[0].Rows[0]["Allowance"].ToString());
                    _allowance = (dsEntityAllowance.Tables[0].Rows[0]["Allowance"].ToString());
                    _currency = (dsEntityAllowance.Tables[0].Rows[0]["CurrencyId"].ToString());
                }
            }
            else
            {

            }
        }
        catch (Exception ex)
        {
            throw ex;
        }
    }
