    public void GetLastApprovedEffectiveDate(string EmpId, out System.Data.DataSet dsRef)
    {
        string strSQL;
        ConnectionManager.DAL.ConManager objCon;
        try
        {
            strSQL = @" select y.SystemID, FORMAT(y.EffectiveDate,'dd-MMM-yyyy') EffectiveDate,y.SalaryRuleMasterSystemID from (SELECT Max(EffectiveDate) EffectiveDate FROM						
                        (SELECT Max(EffectiveDate) EffectiveDate FROM SalaryInfoDefineMaster  WHERE EmpInfoSystemID =  '" + EmpId + @"' and IsApproved =1
                        union
                        SELECT Max(EffectiveDate) EffectiveDate FROM SalaryInfoBackMaster  WHERE EmpInfoSystemID =  '" + EmpId + @"' and IsApproved =1
						) s) x
						left join 
						( SELECT systemid,EffectiveDate,SalaryRuleMasterSystemID FROM SalaryInfoDefineMaster  WHERE EmpInfoSystemID =  '" + EmpId + @"' and IsApproved =1
                        union
                        SELECT systemid,EffectiveDate,SalaryRuleMasterSystemID FROM SalaryInfoBackMaster  WHERE EmpInfoSystemID =  '" + EmpId + @"' and IsApproved =1
						) y 
						on x.EffectiveDate=y.EffectiveDate where y.SystemID is not null ";


            objCon = new ConnectionManager.DAL.ConManager("1");
            objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            objCon = null;
        }
    }//End Function 
    public void GetSalaryID(string EmpId, string ApprovedType, out System.Data.DataSet dsRef)
    {
        string strSQL;
        ConnectionManager.DAL.ConManager objCon;
        try
        {
            strSQL = @"SELECT SystemID
                        FROM SalaryInfoDefineMaster
                        WHERE EmpInfoSystemID = '" + EmpId + @"' AND EffectiveDate =(SELECT Max(EffectiveDate)
                        FROM SalaryInfoDefineMaster  WHERE EmpInfoSystemID = '" + EmpId + @"' and IsApproved = " + ApprovedType + @")  and IsApproved = " + ApprovedType;


            objCon = new ConnectionManager.DAL.ConManager("1");
            objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            objCon = null;
        }
    }//End Function 
    public void GetApprovedInfo(string EmpId, string EffDate, out System.Data.DataSet dsRef)
    {
        string strSQL;
        ConnectionManager.DAL.ConManager objCon;
        try
        {
            strSQL = @"SELECT SystemID, Replace(CONVERT(VARCHAR(11), EffectiveDate, 106), ' ', '-') EffectiveDate
                            FROM SalaryInfoDefineMaster
                            WHERE EmpInfoSystemID = '" + EmpId + @"' AND EffectiveDate ='" + EffDate + @"'  and IsApproved = 1";

            objCon = new ConnectionManager.DAL.ConManager("1");
            objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            objCon = null;
        }
    }//End Function 
