    public void GetApprovedSalaryDetails(string PlantId, string EmpSystemId, string EffictiveDate, out DataTable dtRef)
    {
        DataSet dsRef = null;
        ConnectionManager.DAL.ConManager objCon;
        try
        {

            string strSql = @" SELECT * FROM (
                              SELECT --SDM.EmpInfoSystemID,FORMAT(EffectiveDate,'dd-MMM-yyyy') EffectiveDate--,SH.*

                                SH.HeadCategory HeadCategory,
                                1 IsSelectSlrHd
                                ,SIDD.systemid   SlrInfoDefSystemID
                                ,SDM.EmpInfoSystemID
                                ,SDM.SalaryRuleMasterSystemID
                                ,SRM.SalaryRuleName
                                ,SRM.SalaryRuleDescription
                                ,'' CurrencyRuleSystemID---
                                ,'' CurrencyRuleChildSystemID--
                                ,'' TagAndUnTag--
                                ,SIDD.SalaryHeadID
                                ,SH.SalaryHead
                                ,case when SH.HeadType='E' then 'Earning'  when SH.HeadType='D' then 'Deduction' else  SH.HeadType end HeadType 
                                ,SIDD.EntryCurrencyID
                                ,'' EntryCurrency--
                                ,'' DefinitionCurrencyID--
                                ,'' DefinitionCurrency--
                                ,'' DisbusmentCurrencyID--
                                ,'' DisbusmentCurrency--
                                ,'' FormulaDes--
                                ,'' FormulaDesID--
                                ,'' FixedValue--
                                ,'' IsOpen--
                                ,'' IsNA--
                                ,SIDD.EntryAmount
                                ,SIDD.DefineAmount
                                --,SIDD.SequenceNo
                                , ISNULL(srg.SequenceNo,0) SequenceNo, ISNULL(srg.IsSlabBased,0) IsSlabBased
                                ,FORMAT(SDM.EffectiveDate,'dd-MMM-yyyy') EffectiveDate
                                ,'' EndDate--
                                ,'' MonthPeriod--
                                ,SIDD.AmtDefinitionCurrencyID
                                ,SIDD.AmtDefinitionRate
                                ,SDM.IsApproved
                                --,'' HeadCategory--
                                ,'' BaseOnNetPay--
                                ,'' RefAbsentism--
                                --,SH.IsCTCComponent
                                ---,SH.IsGrossComponent
                                ,'' IsGNRBaseOthSlrHD--
                                ,'' GNRBaseOthSlrHDFormula--
                                ,'' GNRApplicableMonthNo--
                                ,'' EarningCurrencyID--
                                ,'' EarningAmount--
                                ,'' IsGNRWhichEverLess--
                                ,'' RoundOption--
                                ,'' IntegerInDisb--
                                ,'' IsDecimalInDisb
                                ,'' DecimalNo
                                ,SIDD.SalaryCategory
                                , ISNULL(srg.SequenceNo,0) SalaryHdSequence--
                                ,SIDD.SalaryID


								
								
								
                                FROM SalaryInfoDefineMaster SDM
                                LEFT JOIN salaryinfodefine SIDD ON SIDD.SalaryID=SDM.SystemID
                                LEFT JOIN SalaryHead SH on SH.SalaryHeadID=SIDD.SalaryHeadID
                                LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID=SDM.SalaryRuleMasterSystemID
                                LEFT JOIN SalaryRuleGeneral AS srg ON srg.SalaryRuleMasterSystemID = SRM.SystemID AND srg.SalaryHeadID = SH.SalaryHeadID
                                Where SDM.EmpInfoSystemID='" + EmpSystemId + @"' and SDM.EffectiveDate='" + EffictiveDate + @"' and SDM.PlantId='" + PlantId + @"'
                                union
                                SELECT   SH.HeadCategory HeadCategory,
                                1 IsSelectSlrHd
                                ,SIDD.systemid   SlrInfoDefSystemID
                                ,SDM.EmpInfoSystemID
                                ,SDM.SalaryRuleMasterSystemID
                                ,SRM.SalaryRuleName
                                ,SRM.SalaryRuleDescription
                                ,'' CurrencyRuleSystemID---
                                ,'' CurrencyRuleChildSystemID--
                                ,'' TagAndUnTag--
                                ,SIDD.SalaryHeadID
                                ,SH.SalaryHead
                                ,case when SH.HeadType='E' then 'Earning'  when SH.HeadType='D' then 'Deduction' else  SH.HeadType end HeadType  
                                ,SIDD.EntryCurrencyID
                                ,'' EntryCurrency--
                                ,'' DefinitionCurrencyID--
                                ,'' DefinitionCurrency--
                                ,'' DisbusmentCurrencyID--
                                ,'' DisbusmentCurrency--
                                ,'' FormulaDes--
                                ,'' FormulaDesID--
                                ,'' FixedValue--
                                ,'' IsOpen--
                                ,'' IsNA--
                                ,SIDD.EntryAmount
                                ,SIDD.DefineAmount
                                , ISNULL(srg.SequenceNo,0) SequenceNo,ISNULL(srg.IsSlabBased,0) IsSlabBased
                                ,FORMAT(SDM.EffectiveDate,'dd-MMM-yyyy') EffectiveDate
                                ,'' EndDate--
                                ,'' MonthPeriod--
                                ,SIDD.AmtDefinitionCurrencyID
                                ,SIDD.AmtDefinitionRate
                                ,SDM.IsApproved
                                --,'' HeadCategory--
                                ,'' BaseOnNetPay--
                                ,'' RefAbsentism--
                                --,SH.IsCTCComponent
                                --,SH.IsGrossComponent
                                ,'' IsGNRBaseOthSlrHD--
                                ,'' GNRBaseOthSlrHDFormula--
                                ,'' GNRApplicableMonthNo--
                                ,'' EarningCurrencyID--
                                ,'' EarningAmount--
                                ,'' IsGNRWhichEverLess--
                                ,'' RoundOption--
                                ,'' IntegerInDisb--
                                ,'' IsDecimalInDisb
                                ,'' DecimalNo
                                ,SIDD.SalaryCategory
                                , ISNULL(srg.SequenceNo,0) SalaryHdSequence--
                                ,SIDD.SalaryID

                                FROM SalaryInfoBackMaster SDM
                                LEFT JOIN salaryinfoback SIDD ON SIDD.SalaryID=SDM.SystemID
                                LEFT JOIN SalaryHead SH on SH.SalaryHeadID=SIDD.SalaryHeadID
                                LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID=SDM.SalaryRuleMasterSystemID
                                LEFT JOIN SalaryRuleGeneral AS srg ON srg.SalaryRuleMasterSystemID = SRM.SystemID AND srg.SalaryHeadID = SH.SalaryHeadID
                                Where SDM.EmpInfoSystemID='" + EmpSystemId + @"' and SDM.EffectiveDate='" + EffictiveDate + @"' and SDM.PlantId='" + PlantId + @"' 
                                ) a ORDER BY a.SalaryHdSequence ";





            objCon = new ConnectionManager.DAL.ConManager("1");
            objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, "1");
            dtRef = dsRef.Tables[0];

        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            objCon = null;
        }
    }


