            bool IsPFEntitle = false;
            bool IsPFNotEntitleGetAllo = false;




            GetPFtagUntagDetailsByPolicy(PlantId, EmpSystemId, out dtPfTagUnTagEmp);

            if (dtPfTagUnTagEmp.Rows.Count > 0)
            {

            }





























































            string sEmpSysID = "";
            objPFPrc.GetPFEligibleEmployee(sEmpSysID, out dsPFEntitle);
            if (dsPFEntitle.Tables[0].Rows.Count > 0)
            {
                string sPFMstID = dsPFEntitle.Tables[0].Rows[0]["PFMstID"].ToString();
                objPFPrc.GetPFPolicyDetails(sPFMstID, out dsPFPolDtl);
                PFEffectiveDate = Convert.ToDateTime(dsPFEntitle.Tables[0].Rows[0]["StartDate"].ToString()).ToString("dd-MMM-yyyy");


