                if (PFSettingModel.IsbuttonPFClicked == "YES")//if anytime user went to the pf setting
                {

                }
                else//user never went to the pf setting
                {
                    if (Convert.ToBoolean(dsPFEntitle.Tables[0].Rows[0]["IsActive"].ToString()) == true && Convert.ToBoolean(dsPFEntitle.Tables[0].Rows[0]["IsApproved"].ToString()) == true)
                    {
                        IsPFEntitle = true;
                    }
                    else
                    {
                        IsPFEntitle = false;
                    }
                }
                if (IsPFEntitle == false)
                {
                    PFEffectiveDate = "";

                }


                if (Convert.ToBoolean(dsPFPolDtl.Tables[0].Rows[0]["IsNotEntGetEmplrAlwn"].ToString()) == true)
                {

                    IsPFNotEntitleGetAllo = Convert.ToBoolean(dsPFPolDtl.Tables[0].Rows[0]["IsNotEntGetEmplrAlwn"].ToString());
                }
                else
                {

                    IsPFNotEntitleGetAllo = Convert.ToBoolean(dsPFPolDtl.Tables[0].Rows[0]["IsNotEntGetEmplrAlwn"].ToString());
                }

                //if (Convert.ToBoolean(dsPFEntitle.Tables[0].Rows[0]["IsMandatory"]) == true)
                //{
                //    IsPFEntitle = false;
                //    IsPFNotEntitleGetAllo = false;
                //}
                //else
                //{
                //    IsPFEntitle = true;
                //    IsPFNotEntitleGetAllo = true;
                //}

            }
            else
            {
                Exception ex = new Exception("PF policy not define...");
                throw (ex);
            }
            if (PFSettingModel.IsbuttonPFClicked.ToUpper() == "NO")
            {
                retResult.IsPFEntitle = IsPFEntitle;
                retResult.IsPFNotEntitleGetAllo = IsPFNotEntitleGetAllo;
                retResult.PFEffectiveDate = PFEffectiveDate;
                retResult.EmpSystemId = pEmpSystemid;
                retResult.IsbuttonPFClicked = "YES";

            }
            if (PFSettingModel.IsbuttonPFClicked.ToUpper() == "YES")
            {
                retResult.IsPFEntitle = PFSettingModel.IsPFEntitle;
                retResult.IsPFNotEntitleGetAllo = PFSettingModel.IsPFNotEntitleGetAllo;
                retResult.PFEffectiveDate = PFSettingModel.PFEffectiveDate;
                retResult.EmpSystemId = pEmpSystemid;
                retResult.IsbuttonPFClicked = "YES";

            }


            return retResult;
        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            //
        }
    }

    public void PFCheckAndUnCheckDone(string EmpSystemId, bool IsPFEntitle, string PFEffectiveDate, bool bSave, string User)
    {
        #region Declear DataSet
        DataSet dsPFEntitle = null;
        DataTable dtPFEntitle = null;
