                        drPFEntitle["UpdatedDate"] = DateTime.Now;
                        drPFEntitle.EndEdit();
                        #endregion PF Eligible Employee
                    }
                    objStatic.SaveDataSets(dsPFEntitle);

                    //GeneratePFSalaryDefine(dsLocal);
                }
            }
            else if (IsPFEntitle == false)
            {
                if (bEntitle == true)
                {
                    #region PF Eligible Employee

                    PFEffectiveDate = "";
                    dvPFEntitle.RowFilter = "EmpSystemID ='" + EmpSystemId + "'";
                    if (dvPFEntitle.Count == 1)
                    {
                        drPFEntitle = dvPFEntitle[0].Row;
                        drPFEntitle.BeginEdit();
                        drPFEntitle["IsActive"] = false;
                        drPFEntitle["IsApproved"] = true;

                        drPFEntitle["AddedFromIP"] = "";
                        drPFEntitle["UpdatedBy"] = bplib.clsWebLib.RetValidLen(User);
                        drPFEntitle["UpdatedDate"] = DateTime.Now;
                        drPFEntitle.EndEdit();
                    }

                    #endregion PF Eligible Employee

                    #region Remove From Salary Info Define

                    //for (int i = 0; i < dsLocal.Tables[0].Rows.Count; i++)
                    //{
                    //    if (dsLocal.Tables[0].Rows[i]["SalaryCategory"].ToString() == "PF")
                    //    {


                    //        drLocal = dsLocal.Tables[0].Rows[i];
                    //        drLocal["EntryAmount"] = "0";
                    //        drLocal["DefineAmount"] = "0";
                    //        drLocal.EndEdit();
                    //    }
                    //}

                    //dgEmpSalaryDefine.DataSource = dsLocal.Tables[0];
                    //dgEmpSalaryDefine.DataBind();

                    #endregion Remove From Salary Info Define
                }
            }

            if (bSave == true)
            {
                string sPFEligibleEmpID = "";

                dvPFEntitle.RowFilter = "EmpSystemID ='" + EmpSystemId + "'";
                if (dvPFEntitle.Count == 1)
                {
                    #region PF Eligible Employee

                    sPFEligibleEmpID = dvPFEntitle[0].Row["ID"].ToString();

                    drPFEntitle = dvPFEntitle[0].Row;
                    drPFEntitle.BeginEdit();
                    drPFEntitle["IsActive"] = IsPFEntitle;
                    drPFEntitle["IsApproved"] = true;

                    drPFEntitle["AddedFromIP"] = "";
                    drPFEntitle["UpdatedBy"] = bplib.clsWebLib.RetValidLen(User);
                    drPFEntitle["UpdatedDate"] = DateTime.Now;
                    drPFEntitle.EndEdit();
                    #endregion PF Eligible Employee
                }

                if (IsPFEntitle == false)
                {
                    objINC.DeletePFAftEnt(sPFEligibleEmpID);
                }
                objStatic.SaveDataSets(dsPFEntitle);
            }


        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            //
        }
    }//End Function

