    #region Salary Structure Approval
    public void GetSalaryAdditionalData(string EmpSystemId, string SalaryStructureId, out DataSet dsRef)
    {

        ConnectionManager.DAL.ConManager objCon;
        try
        {

            string strSql = @"SELECT sidm.EmpInfoSystemID,sidm.SystemID,sidm.EffectiveDate,sid1.SalaryHeadID,
                                           sid1.EntryAmount, sh.SalaryHead, sh.HeadCategory
                                    FROM SalaryInfoDefineMaster AS sidm
                                    LEFT JOIN SalaryInfoDefine AS sid1 ON sidm.SystemID=sid1.SalaryID
                                    LEFT JOIN SalaryHead AS sh ON sh.SalaryHeadID = sid1.SalaryHeadID
                                    WHERE sidm.EmpInfoSystemID='" + EmpSystemId + @"'  AND sidm.SystemID='" + SalaryStructureId + @"' AND sid1.EntryAmount>0
                                    AND (sh.HeadCategory='PF VOLUNTARY'
                                    OR sh.HeadCategory='PF EMPLOYER CONTRIBUTION'
                                    OR sh.HeadCategory='PF EMPLOYEE CONTRIBUTION'
                                    OR sh.HeadCategory='PENSION'
                                    OR sh.HeadCategory='ESIC EMPLOYER CONTRIBUTION'
                                    OR sh.HeadCategory='ESIC EMPLOYEE CONTRIBUTION'
                                    OR sh.HeadCategory='OTHER BONUS'
                                    OR sh.HeadCategory='EX-GRATIA'
                                    ) ";

            objCon = new ConnectionManager.DAL.ConManager("1");
            objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, "1");


        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            objCon = null;
        }
    }

    public void GetEmployeeEligibleForSalaryHeadEnumData(string EmpSystemId, string SalaryStructureId, out DataSet dsRef)
    {

        ConnectionManager.DAL.ConManager objCon;
        try
        {

            string strSql = @"SELECT * FROM EmployeeEligibleForSalaryHeadEnum WHERE EmpSystemId='" + EmpSystemId + @"' AND IsEligible=1 AND SalaryStructureId='" + SalaryStructureId + @"'";

            objCon = new ConnectionManager.DAL.ConManager("1");
            objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, "1");


        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            objCon = null;
        }
    }

