    void ValidationSave(string EmpSystemId, string EffectiveDate)
    {
        clsSalaryInfoNew objINC = null;
        DataSet dsEffectiveDate = null;
        try
        {
            objINC = new clsSalaryInfoNew();
            objINC.GetSalaryInfoDefineMasterForValidation(EmpSystemId, EffectiveDate, out dsEffectiveDate);
            if (dsEffectiveDate.Tables[0].Rows.Count > 0)
            {
                if (bplib.clsWebLib.GetBoolData(dsEffectiveDate.Tables[0].Rows[0]["IsApproved"].ToString()))
                {
                    bplib.clsWebLib.Throw("Salary Structure has already been approved for this and Effective Date [" + dsEffectiveDate.Tables[0].Rows[0]["EffectiveDate"].ToString() + "]");
                }
            }
            else
            {
                bplib.clsWebLib.Throw("No Salary Structure found for this for the Effective Date [" + EffectiveDate + "]");
            }
        }
        catch (Exception ex)
        {
            throw ex;
        }
    }



