    public void GetPFtagUntagDetailsByPolicy(string PlantId, string EmpSystemId, out DataTable dtRef)
    {
        DataSet dsRef = null;
        ConnectionManager.DAL.ConManager objCon;
        try
        {

            string strSql = @" SELECT PFPDetails.*
                            , DM.PFPolicyMasterID
                            , PFPLMst.Eligibility
                            , PFPLMst.EligibilityBaseOn
                            , PFPLMst.EligibilityTimeLenght
                            , PFPLMst.MaturityBaseOn
                            , PFPLMst.MaturityTimeLenght
                            FROM [dbo].[EmployeeInformation] E
			
                                            INNER JOIN (
                                                        SELECT DC.LeavePolicyMasterId, DC.PFPolicyMasterID, D.DesignationId 
                                                        FROM MST.DesignationMaster D
									                            LEFT JOIN SCS.DesignationMasterConfiguration DC ON D.Id=DC.DesignationMasterId
							                            WHERE DC.PlantId='" + PlantId + @"'
                                                        ) DM ON E.GivenDesignationId = DM.DesignationId
				
			                                LEFT JOIN [dbo].[PFPolicyMaster] PFPLMst ON DM.PFPolicyMasterID = PFPLMst.ID
                                            LEFT JOIN [dbo].[PFPolicyDetails] PFPDetails ON PFPDetails.PFPolicyMasterID = PFPLMst.ID
                            WHERE  E.PlantId = '" + PlantId + @"' 
                            AND E.SystemId IN ('" + EmpSystemId + @"') ";

            objCon = new ConnectionManager.DAL.ConManager("1");
            objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, "1");
            dtRef = dsRef.Tables[0];

        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            objCon = null;
        }
    }
    public void GetunApprovedSalaryDetailsForapproval(string PlantId, string EmpSystemId, out DataTable dtRef)
    {
        DataSet dsRef = null;
        ConnectionManager.DAL.ConManager objCon;
        try
        {

            string strSql = @" SELECT * FROM (
                              SELECT --SDM.EmpInfoSystemID,FORMAT(EffectiveDate,'dd-MMM-yyyy') EffectiveDate--,SH.*

                                --SH.HeadCategory HeadType,
                                1 IsSelectSlrHd
                                ,SIDD.systemid   SlrInfoDefSystemID
                                ,SDM.EmpInfoSystemID
                                ,SDM.SalaryRuleMasterSystemID
                                ,SRM.SalaryRuleName
                                ,SRM.SalaryRuleDescription
                                ,'' CurrencyRuleSystemID---
                                ,'' CurrencyRuleChildSystemID--
                                ,'' TagAndUnTag--
                                ,SIDD.SalaryHeadID
                                ,SH.SalaryHead
                                ,case when SH.HeadType='E' then 'Earning' else         SH.HeadType end HeadType 
                                ,SIDD.EntryCurrencyID
                                ,'' EntryCurrency--
                                ,'' DefinitionCurrencyID--
                                ,'' DefinitionCurrency--
                                ,'' DisbusmentCurrencyID--
                                ,'' DisbusmentCurrency--
                                ,'' FormulaDes--
                                ,'' FormulaDesID--
                                ,'' FixedValue--
                                ,'' IsOpen--
                                ,'' IsNA--
                                ,SIDD.EntryAmount
                                ,SIDD.DefineAmount
                                ,SIDD.SequenceNo
                                ,FORMAT(SDM.EffectiveDate,'dd-MMM-yyyy') EffectiveDate
                                ,'' EndDate--
                                ,'' MonthPeriod--
                                ,SIDD.AmtDefinitionCurrencyID
                                ,SIDD.AmtDefinitionRate
                                ,SDM.IsApproved
                                ,'' HeadCategory--
                                ,'' BaseOnNetPay--
                                ,'' RefAbsentism--
                                ---,SH.IsCTCComponent
                                ---,SH.IsGrossComponent
                                ,'' IsGNRBaseOthSlrHD--
                                ,'' GNRBaseOthSlrHDFormula--
                                ,'' GNRApplicableMonthNo--
                                ,'' EarningCurrencyID--
                                ,'' EarningAmount--
                                ,'' IsGNRWhichEverLess--
                                ,'' RoundOption--
                                ,'' IntegerInDisb--
                                ,'' IsDecimalInDisb
                                ,'' DecimalNo
                                ,SIDD.SalaryCategory
                                ,SH.Sequence SalaryHdSequence--
                                ,SIDD.SalaryID
                                ,EI.EmployeeCode

								
								
								
                                FROM SalaryInfoDefineMaster SDM
                                LEFT JOIN salaryinfodefine SIDD ON SIDD.SalaryID=SDM.SystemID
                                LEFT JOIN SalaryHead SH on SH.SalaryHeadID=SIDD.SalaryHeadID
                                LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID=SDM.SalaryRuleMasterSystemID
								left join EmployeeInformation EI ON EI.SystemId=SDM.EmpInfoSystemID
                                Where SDM.EmpInfoSystemID='" + EmpSystemId + @"' and SDM.IsApproved=0 and SDM.PlantId='" + PlantId + @"'
                               
                                ) a";





            objCon = new ConnectionManager.DAL.ConManager("1");
            objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, "1");
            dtRef = dsRef.Tables[0];

        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            objCon = null;
        }
    }



    public void GetApprovedSalaryRuleIdByEmpId(string EmpSystemId, out DataTable dtRef)
    {
        DataSet dsRef = null;
        ConnectionManager.DAL.ConManager objCon;
        try
        {

            string strSql = @" 
  	                            SELECT (x.EffectiveDate) EffectiveDate,m.SystemID,m.SalaryRuleMasterSystemID from 
  	                            (	--**		
  	 	                            select max(	EffectiveDate) 	EffectiveDate FROM (
                                                    SELECT  EffectiveDate FROM SalaryInfoDefineMaster  WHERE EmpInfoSystemID =  '" + EmpSystemId + @"' and IsApproved =1 --AND EffectiveDate<='13-Dec-2019'
                                                    union
                                                    SELECT  EffectiveDate  FROM SalaryInfoBackMaster  WHERE EmpInfoSystemID =  '" + EmpSystemId + @"' and IsApproved =1 --AND EffectiveDate<='13-Dec-2019'
  	 	                            ) zz
	                            ) x
	                            --**
						
	                            INNER JOIN (
			                            SELECT  EffectiveDate,SystemID,SalaryRuleMasterSystemID
			                            FROM SalaryInfoDefineMaster  WHERE EmpInfoSystemID =  '" + EmpSystemId + @"' and IsApproved =1 
                                union
                                SELECT  EffectiveDate,SystemID,SalaryRuleMasterSystemID FROM SalaryInfoBackMaster  WHERE EmpInfoSystemID =  '" + EmpSystemId + @"' and IsApproved =1 
	                            ) m ON m.EffectiveDate=x.EffectiveDate ";





            objCon = new ConnectionManager.DAL.ConManager("1");
            objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, "1");
            dtRef = dsRef.Tables[0];

        }
        catch (Exception ex)
        {
            throw (ex);
        }
        finally
        {
            objCon = null;
        }
    }

